"use strict";(self["webpackChunkhanv3"]=self["webpackChunkhanv3"]||[]).push([[646],{64646:function(e,a,t){t.r(a),t.d(a,{default:function(){return z}});var d=t(73396),s=t(68220),i=t(83140),c=t(67598),n=t(55709),o=t(77166),r=t(59338),l=t(78073),v=t(22706),h=t(20049),p=t(26742),u=t(83481),m=t(24294),g=t(28049),f=t(52084),w=t(46024),b=t(91530),y=t(68516),k=t(60883),S=t(78787),I=t(74480),q=t(45133);const D=e=>((0,d.dD)("data-v-8d32dec4"),e=e(),(0,d.Cn)(),e),T={class:"work-auth-view"},A=(0,d.uE)('<nav data-v-8d32dec4><div class="container" data-v-8d32dec4><a href="/" data-v-8d32dec4><div class="logos" data-v-8d32dec4><img src="'+s+'" alt="" data-v-8d32dec4><h4 data-v-8d32dec4>Han Wang</h4></div><a href="/work" class="link" data-v-8d32dec4><img src="'+i+'" data-v-8d32dec4></a></a></div></nav>',1),C={class:"work-auth-container font"},x=(0,d.uE)('<section class="landing" data-v-8d32dec4><div class="container small" data-v-8d32dec4><span class="kicker" data-v-8d32dec4>Strategic Service Design · 2025</span><h1 data-v-8d32dec4>From fragmented systems<br data-v-8d32dec4>to a strategic blueprint.</h1><p class="lede" data-v-8d32dec4> Reimagining the authenticated student experience for a leading higher-education institution — moving the conversation from &quot;what should it look like&quot; to &quot;what should we build, and why.&quot; </p><div class="hero-tags" data-v-8d32dec4><span class="hero-tag" data-v-8d32dec4>Strategic Design</span><span class="hero-tag" data-v-8d32dec4>UX Research</span><span class="hero-tag" data-v-8d32dec4>UX Design</span><span class="hero-tag" data-v-8d32dec4>Stakeholder Management</span><span class="hero-tag" data-v-8d32dec4>AI-powered Workflow</span></div><div class="meta" data-v-8d32dec4><div class="meta-item" data-v-8d32dec4><h6 data-v-8d32dec4>My Role</h6><p data-v-8d32dec4>Sole full-time Experience Designer, partnered with one Design Lead and a part-time intern.</p></div><div class="meta-item" data-v-8d32dec4><h6 data-v-8d32dec4>Context</h6><p data-v-8d32dec4>During my time as an Experience Design Analyst on the in-house service design team, I led the discovery and concept design of this strategic initiative — partnering with engineering, operations, and student-services leaders across the year.</p></div><div class="meta-item" data-v-8d32dec4><h6 data-v-8d32dec4>Outcome</h6><p data-v-8d32dec4>A solution-requirements blueprint and phased roadmap that secured executive endorsement and informed capital-funding allocation.</p></div></div></div></section>',1),E={class:"hmw"},W={class:"container small"},j={class:"hmw-grid"},P=(0,d.uE)('<div class="hmw-text" data-v-8d32dec4><span class="section-label" data-v-8d32dec4>Opportunity Statement</span><h2 class="hmw-q" data-v-8d32dec4> How might we improve the <em data-v-8d32dec4>authenticated experience</em> for current students? </h2><p class="hmw-sub" data-v-8d32dec4> Three pain points kept surfacing across every research session — and together, they framed the central question we set out to answer. </p><div class="pain-points" data-v-8d32dec4><div class="pain-point" data-v-8d32dec4><span class="pain-num" data-v-8d32dec4>01</span><div class="pain-body" data-v-8d32dec4><h5 data-v-8d32dec4>Disconnected Systems</h5><p data-v-8d32dec4>Students must navigate multiple platforms for basic information, often starting outside the institution altogether via web search.</p></div></div><div class="pain-point" data-v-8d32dec4><span class="pain-num" data-v-8d32dec4>02</span><div class="pain-body" data-v-8d32dec4><h5 data-v-8d32dec4>Constant Re-authentication</h5><p data-v-8d32dec4>Persistently needing to log in between systems was the highest-priority pain point students surfaced, fragmenting otherwise simple tasks.</p></div></div><div class="pain-point" data-v-8d32dec4><span class="pain-num" data-v-8d32dec4>03</span><div class="pain-body" data-v-8d32dec4><h5 data-v-8d32dec4>Opaque Support Processes</h5><p data-v-8d32dec4>Students lose confidence chasing service requests through systems that don&#39;t reveal status — leading to unnecessary support calls and erosion of trust.</p></div></div></div></div>',1),R={class:"hmw-figure"},H=["src"],F=D((()=>(0,d._)("figcaption",null," Our Vision: from disconnected systems, repeated authentication, and opaque support — toward a unified digital home, seamless action, and proactive intelligence. ",-1))),M=(0,d.uE)('<section class="methodology" data-v-8d32dec4><div class="container small" data-v-8d32dec4><span class="section-label" data-v-8d32dec4>Methodology</span><h2 data-v-8d32dec4>A Double Diamond, in four deliberate moves.</h2><p class="intro" data-v-8d32dec4> The biggest risk in a strategic project is jumping to solutions before you understand the problem. The Double Diamond&#39;s enforced separation between <em data-v-8d32dec4>problem framing</em> and <em data-v-8d32dec4>solution framing</em> gave us — and our stakeholders — a shared map of where we were in the work, and what kind of decisions could be made at each point. Each phase was anchored by a question, an objective, a defined set of activities, and the outcomes we held it accountable for. </p><div class="phase-grid" data-v-8d32dec4><article class="phase-card discover" data-v-8d32dec4><header class="phase-card-head" data-v-8d32dec4><div class="phase-meta" data-v-8d32dec4><span class="phase-num" data-v-8d32dec4>01</span><img src="'+c+'" alt="" data-v-8d32dec4></div><h3 data-v-8d32dec4>Discover</h3></header><div class="phase-question" data-v-8d32dec4><span class="q-label" data-v-8d32dec4>Guiding Question</span><p data-v-8d32dec4>What problems are we solving with a student admin portal?</p></div><div class="phase-objective" data-v-8d32dec4><span class="block-label" data-v-8d32dec4>Objective</span><p data-v-8d32dec4>Build a clear understanding of the current landscape, user needs, and opportunities.</p></div><div class="phase-cols" data-v-8d32dec4><div class="phase-col" data-v-8d32dec4><span class="block-label" data-v-8d32dec4>Activities</span><ul data-v-8d32dec4><li data-v-8d32dec4>Heuristic review of the existing authenticated ecosystem</li><li data-v-8d32dec4>Comparative analysis against peer institutions</li><li data-v-8d32dec4>Discovery interviews and shadowing with students</li><li data-v-8d32dec4>Stakeholder context-setting workshops</li></ul></div><div class="phase-col" data-v-8d32dec4><span class="block-label" data-v-8d32dec4>Outcomes</span><ul data-v-8d32dec4><li data-v-8d32dec4>Identified key pain points across the student admin journey</li><li data-v-8d32dec4>Mapped user behaviours, contexts, and peer offerings</li><li data-v-8d32dec4>Surfaced quick wins achievable on the current technology stack</li><li data-v-8d32dec4>Gap analysis against peer-institution implementations</li><li data-v-8d32dec4>Catalogued emerging tech enabling personalisation and automation</li></ul></div></div></article><article class="phase-card define" data-v-8d32dec4><header class="phase-card-head" data-v-8d32dec4><div class="phase-meta" data-v-8d32dec4><span class="phase-num" data-v-8d32dec4>02</span><img src="'+n+'" alt="" data-v-8d32dec4></div><h3 data-v-8d32dec4>Define</h3></header><div class="phase-question" data-v-8d32dec4><span class="q-label" data-v-8d32dec4>Guiding Question</span><p data-v-8d32dec4>How might we solve student problems with a digital self-service portal?</p></div><div class="phase-objective" data-v-8d32dec4><span class="block-label" data-v-8d32dec4>Objective</span><p data-v-8d32dec4>Explore potential solutions to student problems through digital self-service.</p></div><div class="phase-cols" data-v-8d32dec4><div class="phase-col" data-v-8d32dec4><span class="block-label" data-v-8d32dec4>Activities</span><ul data-v-8d32dec4><li data-v-8d32dec4>Translated insights into structured design hypotheses</li><li data-v-8d32dec4>Tested desirability of future-state product features with students</li><li data-v-8d32dec4>Pressure-tested feasibility of initiative themes with workstream leads</li></ul></div><div class="phase-col" data-v-8d32dec4><span class="block-label" data-v-8d32dec4>Outcomes</span><ul data-v-8d32dec4><li data-v-8d32dec4>Comprehensive list of opportunities organised as conceptual themes</li><li data-v-8d32dec4>Shortlisted high-potential themes refined through student feedback</li><li data-v-8d32dec4>A strategic future-state vision combining new and in-flight improvements</li><li data-v-8d32dec4>Product features defined to support each shortlisted theme</li></ul></div></div></article><article class="phase-card ideate" data-v-8d32dec4><header class="phase-card-head" data-v-8d32dec4><div class="phase-meta" data-v-8d32dec4><span class="phase-num" data-v-8d32dec4>03</span><img src="'+o+'" alt="" data-v-8d32dec4></div><h3 data-v-8d32dec4>Ideate</h3></header><div class="phase-question" data-v-8d32dec4><span class="q-label" data-v-8d32dec4>Guiding Question</span><p data-v-8d32dec4>How might we practically deliver digital service improvements with a portal?</p></div><div class="phase-objective" data-v-8d32dec4><span class="block-label" data-v-8d32dec4>Objective</span><p data-v-8d32dec4>Design conceptual solutions aligned with the program&#39;s strategic goals.</p></div><div class="phase-cols" data-v-8d32dec4><div class="phase-col" data-v-8d32dec4><span class="block-label" data-v-8d32dec4>Activities</span><ul data-v-8d32dec4><li data-v-8d32dec4>Designed target-state product features per theme</li><li data-v-8d32dec4>Assessment workshops with students, operations, and engineering</li></ul></div><div class="phase-col" data-v-8d32dec4><span class="block-label" data-v-8d32dec4>Outcomes</span><ul data-v-8d32dec4><li data-v-8d32dec4>Conceptual designs for each feature, sized to enable meaningful estimation</li><li data-v-8d32dec4>Feasibility and viability estimates produced collaboratively with stakeholders</li><li data-v-8d32dec4>Cross-workstream alignment on operationalisation, case management, and support per theme</li></ul></div></div></article><article class="phase-card deliver" data-v-8d32dec4><header class="phase-card-head" data-v-8d32dec4><div class="phase-meta" data-v-8d32dec4><span class="phase-num" data-v-8d32dec4>04</span><img src="'+r+'" alt="" data-v-8d32dec4></div><h3 data-v-8d32dec4>Deliver</h3></header><div class="phase-question" data-v-8d32dec4><span class="q-label" data-v-8d32dec4>Guiding Question</span><p data-v-8d32dec4>How might we prioritise the highest-impact, lowest-cost opportunities?</p></div><div class="phase-objective" data-v-8d32dec4><span class="block-label" data-v-8d32dec4>Objective</span><p data-v-8d32dec4>Prioritise next actions for design and prepare for implementation.</p></div><div class="phase-cols" data-v-8d32dec4><div class="phase-col" data-v-8d32dec4><span class="block-label" data-v-8d32dec4>Activities</span><ul data-v-8d32dec4><li data-v-8d32dec4>Concept design and prototype build aligned to the phased roadmap</li><li data-v-8d32dec4>Review and refinement of solution requirements and roadmap documentation</li></ul></div><div class="phase-col" data-v-8d32dec4><span class="block-label" data-v-8d32dec4>Outcomes</span><ul data-v-8d32dec4><li data-v-8d32dec4>Clear focus on high-impact, low-cost opportunities</li><li data-v-8d32dec4>A collaboratively defined, phased solution implementation roadmap and concept design set</li></ul></div></div></article></div><div class="phase-outcome" data-v-8d32dec4><img class="outcome-bg" src="'+l+'" alt="Illustration of the final solution blueprint, showing a phased roadmap and the strategic goals it serves." data-v-8d32dec4><span class="outcome-tag" data-v-8d32dec4>Final Outcome</span><p data-v-8d32dec4> A phased implementation roadmap that balances tactical quick wins with longer-term strategic goals — guiding decision-makers in establishing an enhanced, unified student experience aligned to institutional priorities and the technical roadmap. </p></div></div></section><section class="research" data-v-8d32dec4><div class="container small" data-v-8d32dec4><span class="section-label" data-v-8d32dec4>Activities</span><h2 data-v-8d32dec4>A research arc, not a research dump —<br data-v-8d32dec4>each method earning the next one&#39;s right to exist.</h2><p class="intro" data-v-8d32dec4> We weren&#39;t trying to collect the most data — we were trying to build a chain of evidence stakeholders could not dismiss. The methods unfolded in deliberate sequence across the project&#39;s four phases, with each one answering a question the previous couldn&#39;t. </p><div class="research-timeline" data-v-8d32dec4><article class="timeline-item discover" data-v-8d32dec4><div class="timeline-marker" data-v-8d32dec4></div><div class="timeline-content" data-v-8d32dec4><span class="timeline-tag discover" data-v-8d32dec4>Discover</span><h4 data-v-8d32dec4>In-Depth Interviews</h4><p class="timeline-scale" data-v-8d32dec4>13 sessions</p><p class="timeline-why" data-v-8d32dec4> Every other method on this list earned its question from this one. Before frameworks, before scoring models, before stakeholders weighed in — we needed to hear from students themselves. Numbers describe scale; an interview describes meaning. </p><h6 data-v-8d32dec4>WHAT WE DID</h6><p class="timeline-what" data-v-8d32dec4> Semi-structured sessions surfaced the lived friction behind the metrics and revealed the distinct mental models students brought to the ecosystem. Those mental models became the structural backbone for everything we recommended next. </p></div><div class="timeline-image" data-v-8d32dec4><img src="'+v+'" alt="Photo of a research participant during a remote interview session." data-v-8d32dec4></div></article><article class="timeline-item discover" data-v-8d32dec4><div class="timeline-marker" data-v-8d32dec4></div><div class="timeline-content" data-v-8d32dec4><span class="timeline-tag discover" data-v-8d32dec4>Discover</span><h4 data-v-8d32dec4>Comparative Analysis</h4><p class="timeline-why" data-v-8d32dec4> Before designing anything new, we needed to know what students might already expect from a digital experience — and where the bar sat across comparable institutions and adjacent enterprise products. </p><h6 data-v-8d32dec4>What we did</h6><p class="timeline-what" data-v-8d32dec4> Mapped feature inventories, navigation models, and personalisation approaches across peer institutional portals. Surfaced what was table-stakes, what was emerging best-practice, and where genuine differentiation could live. </p></div><div class="timeline-image" data-v-8d32dec4><img src="'+h+'" alt="Comparison of different institutional portal designs." data-v-8d32dec4></div></article><article class="timeline-item discover" data-v-8d32dec4><div class="timeline-marker" data-v-8d32dec4></div><div class="timeline-content" data-v-8d32dec4><span class="timeline-tag discover" data-v-8d32dec4>Discover</span><h4 data-v-8d32dec4>Heuristic Review</h4><p class="timeline-scale" data-v-8d32dec4>150+ pages audited</p><p class="timeline-why" data-v-8d32dec4> Before proposing what to build, we needed a defensible baseline of what was failing — and at what scale. Cost-effective: no recruitment, no scheduling, just structured analytical work. </p><h6 data-v-8d32dec4>What we did</h6><p class="timeline-what" data-v-8d32dec4> Audited the existing pages within our ecosystem against established usability heuristics and best practices. Surfaced recurring patterns rather than isolated bugs — producing an inventory of design debt we could prioritise against. </p></div><div class="timeline-image" data-v-8d32dec4><img src="'+p+'" alt="Illustration of the heuristic review process." data-v-8d32dec4></div></article><article class="timeline-item define" data-v-8d32dec4><div class="timeline-marker" data-v-8d32dec4></div><div class="timeline-content" data-v-8d32dec4><span class="timeline-tag define" data-v-8d32dec4>Define</span><h4 data-v-8d32dec4>Design Hypothesis Brainstorming</h4><p class="timeline-why" data-v-8d32dec4> Insights stay descriptive until you commit to a hypothesis. Without this step, research findings become a comfortable explanation for inaction. Hypothesis brainstorming forced the team to put each insight on the line as a testable bet — before falling in love with it. </p><h6 data-v-8d32dec4>What we did</h6><p class="timeline-what" data-v-8d32dec4> Synthesis sessions translated raw signals from Discover into structured hypotheses. Each one became a candidate solution that the downstream methods — Kano survey, co-design workshops, feasibility reviews — could validate or kill on evidence rather than opinion. </p></div><div class="timeline-image" data-v-8d32dec4><img src="'+u+'" alt="Photo of a whiteboard filled with design hypotheses." data-v-8d32dec4></div></article><article class="timeline-item define" data-v-8d32dec4><div class="timeline-marker" data-v-8d32dec4></div><div class="timeline-content" data-v-8d32dec4><span class="timeline-tag define" data-v-8d32dec4>Define</span><h4 data-v-8d32dec4>Kano Survey</h4><p class="timeline-scale" data-v-8d32dec4>249 survey responses</p><p class="timeline-why" data-v-8d32dec4> Feature requests are infinite; budgets aren&#39;t. The Kano model gave us a quantitative lens on something traditionally driven by loudest-voice prioritisation. </p><h6 data-v-8d32dec4>What we did</h6><p class="timeline-what" data-v-8d32dec4> Each candidate feature was classified as a <em data-v-8d32dec4>Must-Be</em>, a <em data-v-8d32dec4>Performance Feature</em>, or a <em data-v-8d32dec4>Attractive</em>. The framework gave us a calm, defensible answer when stakeholders pushed for personal favourites ahead of basic needs. </p></div><div class="timeline-image" data-v-8d32dec4><img src="'+m+'" alt="Illustration of the Kano result, showing how features are classified into basic needs, performance features, and delighters." data-v-8d32dec4></div></article><article class="timeline-item ideate" data-v-8d32dec4><div class="timeline-marker" data-v-8d32dec4></div><div class="timeline-content" data-v-8d32dec4><span class="timeline-tag ideate" data-v-8d32dec4>Ideate</span><h4 data-v-8d32dec4>Co-design Workshops</h4><p class="timeline-scale" data-v-8d32dec4>50+ participants</p><p class="timeline-why" data-v-8d32dec4> Interviews surface user truth. Workshops surface stakeholder ownership. We needed our recommendations to survive governance — and people defend what they helped build. </p><h6 data-v-8d32dec4>What we did</h6><p class="timeline-what" data-v-8d32dec4> Brought stakeholders, business operations, and service owners into the same room to test future-state themes. The eventual direction wasn&#39;t a recommendation we delivered — it was a position they had helped form. </p></div><div class="timeline-image" data-v-8d32dec4><img src="'+g+'" alt="Photo of a co-design workshop session." data-v-8d32dec4></div></article><article class="timeline-item deliver" data-v-8d32dec4><div class="timeline-marker" data-v-8d32dec4></div><div class="timeline-content" data-v-8d32dec4><span class="timeline-tag deliver" data-v-8d32dec4>Deliver</span><h4 data-v-8d32dec4>Feasibility Assessment</h4><p class="timeline-scale" data-v-8d32dec4>6 technology sessions + 6 business sessions</p><p class="timeline-why" data-v-8d32dec4> Hopes don&#39;t fund roadmaps; cost estimates do. Without stress-testing each high-impact vision story against real engineering effort and operational viability, the prioritisation would have been theatre. This was the gate between &quot;ideas we like&quot; and &quot;stories we can ship.&quot; </p><h6 data-v-8d32dec4>What we did</h6><p class="timeline-what" data-v-8d32dec4> Two parallel tracks. Six workshops with the technology team estimated implementation effort against legacy systems, integrations, and platform constraints. Six conversations with business owners validated operational viability — governance load, support implications, and training cost. The two views collapsed into the <em data-v-8d32dec4>Effort</em> input that downstream RICE prioritisation depended on. </p></div><div class="timeline-image" data-v-8d32dec4><img src="'+f+'" alt="Photo of a feasibility assessment session with engineering stakeholders." data-v-8d32dec4></div></article></div><p class="footnote" data-v-8d32dec4> Findings, quotes, and segment-specific insights are intentionally omitted from this case study to respect institutional confidentiality. The methodology is the transferable part. </p></div></section><section class="prioritise" data-v-8d32dec4><div class="container small" data-v-8d32dec4><span class="section-label" data-v-8d32dec4>Synthesis &amp; Prioritisation</span><h2 data-v-8d32dec4>How we adopted RICE — turning <em data-v-8d32dec4>276 research insights</em> into one comparable score per feature.</h2><p class="intro" data-v-8d32dec4> Synthesis is where strategy lives. We didn&#39;t use RICE as a calculator — we used it as the synthesis spine. Every research signal we collected, from interviews to feasibility workshops, fed into a single shared model that produced one priority score per candidate feature. </p><div class="rice-process" data-v-8d32dec4><div class="rice-step" data-v-8d32dec4><span class="step-num" data-v-8d32dec4>01</span><h5 data-v-8d32dec4>Collect</h5><p data-v-8d32dec4><strong data-v-8d32dec4>276 insights</strong> documented across every research activity — interviews, audits, surveys, workshops, feasibility sessions.</p></div><div class="rice-step" data-v-8d32dec4><span class="step-num" data-v-8d32dec4>02</span><h5 data-v-8d32dec4>Categorise</h5><p data-v-8d32dec4>Each insight tagged to the RICE dimension it spoke to. Tech feedback fed <em data-v-8d32dec4>Effort</em>; student pain fed <em data-v-8d32dec4>Impact</em>; peer benchmarks fed <em data-v-8d32dec4>Confidence</em>.</p></div><div class="rice-step" data-v-8d32dec4><span class="step-num" data-v-8d32dec4>03</span><h5 data-v-8d32dec4>Score</h5><p data-v-8d32dec4>Within its dimension, each insight got a <strong data-v-8d32dec4>1–5 weight</strong> reflecting severity, scale, confidence, or build cost — depending on the bucket.</p></div><div class="rice-step" data-v-8d32dec4><span class="step-num" data-v-8d32dec4>04</span><h5 data-v-8d32dec4>Aggregate &amp; Score</h5><p data-v-8d32dec4>Per candidate feature, contributing insight scores are aggregated statistically into <strong data-v-8d32dec4>R, I, C, and E</strong> values — then collapsed through the RICE formula into a single comparable priority score.</p></div></div><div class="rice-source" data-v-8d32dec4><h3 data-v-8d32dec4>Where each research stream landed in the model.</h3><div class="rice-list" data-v-8d32dec4><div class="rice-row reach" data-v-8d32dec4><span class="rice-letter" data-v-8d32dec4>R</span><div class="rice-content" data-v-8d32dec4><h5 data-v-8d32dec4>Reach</h5><p class="rice-def" data-v-8d32dec4>Who is actually affected.</p><ul data-v-8d32dec4><li data-v-8d32dec4>Student interview cohort breadth</li><li data-v-8d32dec4>Kano survey demographics</li></ul></div></div><div class="rice-row impact" data-v-8d32dec4><span class="rice-letter" data-v-8d32dec4>I</span><div class="rice-content" data-v-8d32dec4><h5 data-v-8d32dec4>Impact</h5><p class="rice-def" data-v-8d32dec4>How much value if delivered.</p><ul data-v-8d32dec4><li data-v-8d32dec4>Kano classification (basic / performance / delighter)</li><li data-v-8d32dec4>Severity of student pain points</li><li data-v-8d32dec4>Co-design priority signals</li></ul></div></div><div class="rice-row confidence" data-v-8d32dec4><span class="rice-letter" data-v-8d32dec4>C</span><div class="rice-content" data-v-8d32dec4><h5 data-v-8d32dec4>Confidence</h5><p class="rice-def" data-v-8d32dec4>How strong is the evidence.</p><ul data-v-8d32dec4><li data-v-8d32dec4>Heuristic review (150+ pages audited)</li><li data-v-8d32dec4>Comparative analysis (peer benchmarks)</li><li data-v-8d32dec4>Cross-method validation</li></ul></div></div><div class="rice-row effort" data-v-8d32dec4><span class="rice-letter" data-v-8d32dec4>E</span><div class="rice-content" data-v-8d32dec4><h5 data-v-8d32dec4>Effort</h5><p class="rice-def" data-v-8d32dec4>What&#39;s the realistic cost.</p><ul data-v-8d32dec4><li data-v-8d32dec4>Technology feasibility (6 sessions)</li><li data-v-8d32dec4>Business viability (6 sessions)</li></ul></div></div></div></div><p class="closer" data-v-8d32dec4> The output wasn&#39;t just &quot;25 vision stories.&quot; It was 25 stories that were both <strong data-v-8d32dec4>wanted by students and realistically deliverable inside the institutional roadmap</strong>. That&#39;s what made the deliverable fundable — not just persuasive. </p></div></section><section class="ai-flow" data-v-8d32dec4><div class="container small" data-v-8d32dec4><span class="section-label ai" data-v-8d32dec4>AI-Powered Workflow</span><h2 data-v-8d32dec4>From requirements document to a living, navigable prototype<br data-v-8d32dec4>— in days, not months.</h2><p class="intro" data-v-8d32dec4> The biggest unlock of the project was treating AI not as a generator of pretty screens, but as a way to <strong data-v-8d32dec4>compress the distance between writing a requirement and feeling what it would be like to use it</strong>. Stakeholders no longer needed imagination — they could click. </p><div class="ai-steps" data-v-8d32dec4><div class="ai-step" data-v-8d32dec4><div class="step-head" data-v-8d32dec4><span class="step-num" data-v-8d32dec4>01</span><h3 data-v-8d32dec4>Solution Requirements as the Source of Truth</h3></div><p data-v-8d32dec4> Each vision story was authored as a structured user story with acceptance criteria, dependencies, and the underlying research insight. This document wasn&#39;t an attachment — it was the <em data-v-8d32dec4>contract</em> the rest of the workflow read from. </p><div class="ai-step-images" data-v-8d32dec4><div class="ai-img-slot" data-v-8d32dec4><img src="'+w+'" alt="Screenshot of a user story with acceptance criteria and research insight annotations." data-v-8d32dec4></div></div></div><div class="connector" data-v-8d32dec4><img src="'+b+'" alt="Illustration of a connector, showing how the user story document feeds into the prototype." data-v-8d32dec4></div><div class="ai-step" data-v-8d32dec4><div class="step-head" data-v-8d32dec4><span class="step-num" data-v-8d32dec4>02</span><h3 data-v-8d32dec4>Generative + Vibe-Coded Functional Prototype</h3></div><p data-v-8d32dec4> We used GenAI tooling and vibe-coding workflows to translate those user stories directly into a working web prototype — not a Figma click-through, but real HTML you could navigate, tab through, and stress-test on mobile. Two parallel prototypes shipped: an <strong data-v-8d32dec4>MVP</strong> view, and a <strong data-v-8d32dec4>Target / Future State</strong> vision. </p><div class="ai-step-images" data-v-8d32dec4><div class="ai-img-slot" data-v-8d32dec4><img src="'+y+'" alt="Screenshot of the MVP prototype." data-v-8d32dec4></div><div class="ai-img-slot" data-v-8d32dec4><img src="'+k+'" alt="Screenshot of the future state prototype." data-v-8d32dec4></div></div></div><div class="connector" data-v-8d32dec4><img src="'+b+'" alt="Illustration of a connector, showing how the prototype feeds into the documentation site." data-v-8d32dec4></div><div class="ai-step" data-v-8d32dec4><div class="step-head" data-v-8d32dec4><span class="step-num" data-v-8d32dec4>03</span><h3 data-v-8d32dec4>A Documentation Site That Holds the Whole Story</h3></div><p data-v-8d32dec4> The final layer was a public-facing documentation site that wove research insights, RICE scores, journey steps, and the live prototypes into one browsable artefact. Decision-makers could move from a roadmap phase to a user story to a working screen in two clicks. <strong data-v-8d32dec4>Alignment stopped being a meeting; it became a hyperlink.</strong></p><div class="ai-step-images" data-v-8d32dec4><div class="ai-img-slot" data-v-8d32dec4><img src="'+S+'" alt="Screenshot of the documentation site." data-v-8d32dec4></div><div class="ai-img-slot" data-v-8d32dec4><img src="'+I+'" alt="Screenshot of the documentation site." data-v-8d32dec4></div></div></div><div class="connector large" data-v-8d32dec4><img src="'+b+'" alt="Illustration of a connector, showing how the prototype feeds into the documentation site." data-v-8d32dec4></div></div><div class="ai-callout" data-v-8d32dec4><span class="callout-tag" data-v-8d32dec4>Why It Mattered</span><h3 data-v-8d32dec4> An interactive artefact removed the most expensive friction in enterprise design — <em data-v-8d32dec4>re-explaining the same idea to a new audience.</em></h3><p data-v-8d32dec4> The prototype and documentation site were directly cited in the materials that secured next-year capital funding for implementation. </p></div></div></section><section class="roadmap" data-v-8d32dec4><div class="container small" data-v-8d32dec4><img class="moun-bg" src="'+q+'" alt="The initiative&#39;s phased roadmap, showing how the MVP, Target State, and Future State features map to short-, mid-, and long-term horizons." data-v-8d32dec4><div class="roadmap-content" data-v-8d32dec4><span class="section-label" data-v-8d32dec4>Strategic Roadmap</span><h2 data-v-8d32dec4>A roadmap is a decision-making artefact,<br data-v-8d32dec4>not a delivery plan.</h2><p class="intro" data-v-8d32dec4> The most strategic deliverable of the project was a phased roadmap framing the short-, mid-, and long-term ambition of the institution&#39;s authenticated experience. It gave leadership a way to talk about technology investment, governance, and future capability in the same shape — which is what allowed the conversation to escalate from a design project to a capital-funded program. </p><p class="closer" data-v-8d32dec4> The point wasn&#39;t to predict the future accurately. It was to give the institution a <strong data-v-8d32dec4>shared horizon</strong> against which every near-term decision could be evaluated. </p><div class="phases" data-v-8d32dec4><div class="phase mvp" data-v-8d32dec4><div class="phase-head" data-v-8d32dec4><span class="badge" data-v-8d32dec4>Short-term</span><h4 data-v-8d32dec4>Foundational Hub</h4></div><p data-v-8d32dec4> Unify visibility of priority information. Reduce friction without rewriting legacy systems. Earn trust through what is shipped, not what is promised. </p><span class="phase-frame" data-v-8d32dec4>Pragmatic, low-risk, high-signal.</span></div><div class="phase target" data-v-8d32dec4><div class="phase-head" data-v-8d32dec4><span class="badge" data-v-8d32dec4>Mid-term</span><h4 data-v-8d32dec4>Seamless &amp; Actionable</h4></div><p data-v-8d32dec4> Move from viewing to doing. Bi-directional integrations let students complete priority tasks without context-switching across systems. </p><span class="phase-frame" data-v-8d32dec4>Capability investment with measurable lift.</span></div><div class="phase future" data-v-8d32dec4><div class="phase-head" data-v-8d32dec4><span class="badge" data-v-8d32dec4>Long-term</span><h4 data-v-8d32dec4>Proactive Intelligence</h4></div><p data-v-8d32dec4> A learning system that anticipates needs, recommends pathways, and surfaces eligibility — informing not just product, but future technology selection. </p><span class="phase-frame" data-v-8d32dec4>Direction-setting for the next decade of investment.</span></div></div></div></div></section><section class="prototype" data-v-8d32dec4><div class="container small" data-v-8d32dec4><span class="section-label" data-v-8d32dec4>Concept Design</span><h2 data-v-8d32dec4>A glimpse, not the focus.</h2><p class="intro" data-v-8d32dec4> Two interactive prototypes — MVP and Target/Future — were generated and refined through the AI-augmented workflow above. They are intentionally treated lightly here; the contribution worth showing is the methodology that produced them, not the screens themselves. </p><div class="prototype-grid" data-v-8d32dec4><div class="proto-card mvp" data-v-8d32dec4><span class="proto-tag" data-v-8d32dec4>MVP</span><div class="proto-frame" data-v-8d32dec4><div class="frame-bar" data-v-8d32dec4><span data-v-8d32dec4></span><span data-v-8d32dec4></span><span data-v-8d32dec4></span></div><div class="frame-body" data-v-8d32dec4><img src="'+y+'" alt="Screenshot of the MVP prototype." data-v-8d32dec4></div></div><p class="proto-caption" data-v-8d32dec4>Foundational hub — view here, do there.</p></div><div class="proto-card future" data-v-8d32dec4><span class="proto-tag" data-v-8d32dec4>Target / Future</span><div class="proto-frame" data-v-8d32dec4><div class="frame-bar" data-v-8d32dec4><span data-v-8d32dec4></span><span data-v-8d32dec4></span><span data-v-8d32dec4></span></div><div class="frame-body" data-v-8d32dec4><img src="'+k+'" alt="Screenshot of the future state prototype." data-v-8d32dec4></div></div><p class="proto-caption" data-v-8d32dec4>Seamless, actionable, and proactively intelligent.</p></div></div></div></section><section class="reflection" data-v-8d32dec4><div class="container small" data-v-8d32dec4><header class="reflection-header" data-v-8d32dec4><span class="section-label" data-v-8d32dec4>Design Thinking</span><h2 data-v-8d32dec4>What this project taught me about<br data-v-8d32dec4>where designers <em data-v-8d32dec4>add value</em>.</h2></header><div class="reflection-grid" data-v-8d32dec4><div class="reflection-col" data-v-8d32dec4><h3 class="r-subhead" data-v-8d32dec4>The pivot — from mocks to blueprints.</h3><p data-v-8d32dec4> When I joined the project, the natural instinct was to deliver a polished frontend redesign. Early conversations with engineering and operations made clear that legacy CMS constraints and entrenched workflows would push back hard against any pixel-led approach. Delivering a Figma file would have produced a beautiful artefact that no one could build. </p><p data-v-8d32dec4> So we changed the deliverable. Instead of mocks, we shipped <strong data-v-8d32dec4>blueprints, user stories, and annotated recommendations</strong> — the kind of artefacts that drive decisions in large organisations. The shift in output was the shift that unlocked the project. </p><blockquote data-v-8d32dec4> In large institutions, defining <em data-v-8d32dec4>what</em> to build often has more impact than specifying <em data-v-8d32dec4>how</em> it looks. </blockquote></div><div class="reflection-col" data-v-8d32dec4><h3 class="r-subhead" data-v-8d32dec4>Intent definition is the new design craft.</h3><p data-v-8d32dec4> As AI continues to lower the cost of producing screens, the designer&#39;s centre of gravity shifts. Visual execution becomes table stakes. The differentiator is the upstream work: framing the right problem, structuring the right evidence, and earning the alignment that lets a recommendation actually become a built thing. </p><p data-v-8d32dec4> The most valuable thing I produced over the year wasn&#39;t a screen. It was a set of artefacts — the user stories, the prioritised roadmap, the AI-generated prototype, the documentation site — that <strong data-v-8d32dec4>told the institution what was worth building, and gave them confidence to fund it</strong>. </p><p data-v-8d32dec4> Designing in large organisations is less about crafting the perfect interface, and more about building the conditions under which the right interface can be built. That, increasingly, is the work. </p></div></div></div></section><section class="ending" data-v-8d32dec4><div class="container small" data-v-8d32dec4><blockquote class="ending-quote" data-v-8d32dec4> A unified digital home: the definitive, primary digital student entry-point and gateway, providing access to unified, priority, and personalised actionable information. </blockquote><span class="ending-label" data-v-8d32dec4>Authenticated Experience strategic value proposition</span></div></section>',8);function O(e,a,s,i,c,n){const o=(0,d.up)("ContactSection");return(0,d.wg)(),(0,d.iD)("div",T,[A,(0,d._)("div",C,[x,(0,d._)("section",E,[(0,d._)("div",W,[(0,d._)("div",j,[P,(0,d._)("figure",R,[(0,d._)("img",{src:t(49404),alt:"Conceptual illustration of a student moving from a fragmented digital experience toward a unified, intelligent one."},null,8,H),F])])])]),M]),(0,d.Wm)(o,{small:!0,bg:"#000F46"})])}var V=t(63151),B=t(69590),_=t(68065),G={name:"WorkAuthView",components:{ContactSection:V.Z},mounted(){(0,B.jq)((0,_.S)({title:"Authenticated Student Experience — Strategic Service Design | Han Wang | Designer, Researcher, Developer",description:"A year-long strategic design initiative reimagining the authenticated student experience for a leading higher-education institution. Discovery, RICE prioritisation, AI-powered prototyping, and a phased roadmap that secured executive endorsement.",path:"/work/authux",image:(0,_.f)("auth"),type:"article"}))}},K=t(40089);const Q=(0,K.Z)(G,[["render",O],["__scopeId","data-v-8d32dec4"]]);var z=Q}}]);
